class Solution:
    def countStaircase(self, nums: list[int]) -> int:
        n = len(nums)
        ans = 0
        for i in range(n):
            orders = {}
            cnt = defaultdict(int)
            ok = 0
            for j in range(i, n):
                x = nums[j]
                if x not in orders:
                    orders[x] = len(orders) + 1
                cnt[x] += 1
                if cnt[x] > orders[x]:
                    break
                if cnt[x] == orders[x]:
                    ok += 1
                    if ok == len(cnt):
                        ans += 1
        return ans

class Solution {
    public int countStaircase(int[] nums) {
        int n = nums.length;
        int ans = 0;
        for (int i = 0; i < n; ++i) {
            var orders = new HashMap<Integer, Integer>();
            var cnt = new HashMap<Integer, Integer>();
            int ok = 0;
            for (int j = i; j < n; ++j) {
                int x = nums[j];
                orders.putIfAbsent(x, orders.size() + 1);
                int count = cnt.merge(x, 1, Integer::sum);
                int order = orders.get(x);
                if (count > order) {
                    break;
                }
                if (count == order && ++ok == cnt.size()) {
                    ++ans;
                }
            }
        }
        return ans;
    }
}

